// build-kanji-json.js
const fs = require('fs');
const path = require('path');

// 学年別漢字リスト定義
const GRADE_KANJI = {
  g2: ["引","羽","雲","園","遠","黄","何","夏","家","科","歌","画","会","回","海","絵","外","角","楽","活","間","丸","岩","顔","汽","記","帰","弓","牛","魚","京","強","教","近","兄","形","計","研","県","原","戸","古","午","語","工","公","広","交","光","考","行","高","黄","合","谷","国","黒","今","才","細","作","算","止","市","矢","姉","思","紙","寺","自","時","70","首","秋","什","重","宿","春","書","少","場","色","食","心","新","親","図","数","西","声","星","晴","切","雪","船","線","前","組","走","多","太","体","台","谷","知","地","池","知","茶","昼","長","鳥","朝","直","通","弟","店","点","電","刀","冬","当","東","答","頭","同","道","読","内","南","二","肉","馬","売","買","麦","半","番","父","風","分","聞","米","歩","母","方","北","毎","妹","万","明","鳴","毛","門","夜","野","矢","理","用","曜","来","里","理","話"],
  // g3〜g6 も同様に定義可能
};

// 簡易座標生成ロジック (ダミーまたはKanjiVGパーサー)
function generateStrokeData(char) {
  // 漢字1文字から書き順ベクトル（始点・終点）を250x250キャンバス用に正規化して生成
  return {
    char: char,
    yomi: "",
    strokes: [
      [[50, 50], [200, 50]], // 例: 1画目
      [[125, 50], [125, 200]] // 例: 2画目
    ]
  };
}

// 各学年ごとにJSONを出力
Object.keys(GRADE_KANJI).forEach(grade => {
  const data = GRADE_KANJI[grade].map(c => generateStrokeData(c));
  const dir = path.join(__dirname, 'data');
  if (!fs.existsSync(dir)) fs.mkdirSync(dir);
  
  fs.writeFileSync(
    path.join(dir, `kanji-${grade}.json`),
    JSON.stringify(data, null, 2)
  );
  console.log(`kanji-${grade}.json の作成完了 (${data.length}文字)`);
});